-- Apply only to a new staging project first. No destructive schema reset.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users on delete cascade,display_name text check(length(display_name)<=100),age_band text check(age_band in ('16-17','18+')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.admin_members(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users,role text not null check(role in ('owner','editor')),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.service_packages(id uuid primary key default gen_random_uuid(),code text not null unique check(code in ('G10','G20','G50')),price_vnd integer not null check(price_vnd>0),delivery_hours integer not null check(delivery_hours>0),version integer not null default 1,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.service_packages(code,price_vnd,delivery_hours) values('G10',10000,24),('G20',20000,48),('G50',50000,72);
create table public.site_config(id uuid primary key default gen_random_uuid(),bank jsonb,refund_policy text,support text,retention_approved boolean not null default false,release_verified boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.site_config default values;
create table public.orders(id uuid primary key default gen_random_uuid(),idempotency_key uuid not null unique,order_code text not null unique check(order_code ~ '^HC[0-9A-HJKMNP-TV-Z]{12}$'),user_id uuid references auth.users on delete set null,package_code text not null references public.service_packages(code),price_vnd integer not null check(price_vnd>0),delivery_hours integer not null,package_version integer not null,name text not null,phone_e164 text not null,phone_lookup_hmac text not null,email text,inputs jsonb not null,internal_state text not null default 'awaiting_payment' check(internal_state in ('awaiting_payment','payment_claimed','expired','cancelled','paid','in_progress','ready','delivered','refund_pending','refunded')),paid_at timestamptz,expires_at timestamptz not null default now()+interval '48 hours',delivered_at timestamptz,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index orders_user_idx on public.orders(user_id);
create index orders_queue_idx on public.orders(internal_state,created_at);
create table public.order_credentials(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders on delete cascade,secret_digest text not null,pepper_version integer not null default 1,revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,kind text not null check(kind in ('claimed','verified','rejected','reconciled')),amount integer,reference text unique,actor uuid references auth.users,reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index one_verified on public.payment_events(order_id) where kind in ('verified','reconciled');
create table public.reading_results(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,revision integer not null,body text not null,state text not null check(state in ('draft','published','archived')),published_by uuid references auth.users,published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(order_id,revision));
create unique index one_published on public.reading_results(order_id) where state='published';
create table public.attachments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,storage_key text not null unique,bucket text not null check(bucket in ('source-photos','private-results','public-derivatives')),mime text not null,size bigint not null check(size>0 and size<=20971520),checksum text not null,asset_version integer not null default 1,classification text not null check(classification in ('source','private_result','public_derivative')),uploader uuid references auth.users,release_state text not null default 'quarantine' check(release_state in ('quarantine','released','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index attachments_order_idx on public.attachments(order_id);
create table public.reading_history(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users on delete cascade,tool text not null,engine_version text not null,dataset_version text not null,snapshot jsonb not null check(octet_length(snapshot::text)<100000),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index history_user_idx on public.reading_history(user_id);
create table public.content_templates(id uuid primary key default gen_random_uuid(),title text not null,body text not null,version integer not null default 1,author uuid references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.dataset_versions(id uuid primary key default gen_random_uuid(),version text not null unique,content jsonb not null,hash text not null,source_metadata jsonb not null,state text not null check(state in ('draft','published')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.consent_events(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,scope text not null check(scope in ('service_processing','customer_photo_for_private_video','website_public_gallery','youtube_publication','tiktok_publication')),granted boolean not null,asset_id uuid references public.attachments,asset_hash text,asset_version integer,notice_version text not null,age_band text not null check(age_band in ('16-17','18+')),actor uuid references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index consent_order_idx on public.consent_events(order_id,scope,created_at desc);
create table public.public_media(id uuid primary key default gen_random_uuid(),asset_id uuid not null references public.attachments,consent_id uuid not null references public.consent_events,platform text not null check(platform in ('website_public_gallery','youtube_publication','tiktok_publication')),state text not null default 'draft' check(state in ('draft','approved','published','withdrawn')),external_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),order_id uuid not null unique references public.orders,rating integer not null check(rating between 1 and 5),body text not null check(length(body)<=1000),nickname text not null check(length(nickname)<=40),moderation_state text not null default 'pending' check(moderation_state in ('pending','approved','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_events(id uuid primary key default gen_random_uuid(),actor uuid references auth.users,action text not null,resource_id uuid,changed_fields text[] not null default '{}',request_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.abuse_counters(id uuid primary key default gen_random_uuid(),key text not null,route text not null,window_id bigint not null,count integer not null default 1,expires_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(key,route,window_id));
create table public.lookup_sessions(id uuid primary key default gen_random_uuid(),token_digest text not null unique,csrf_digest text not null,order_id uuid not null references public.orders on delete cascade,expires_at timestamptz not null default now()+interval '15 minutes',revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.deletion_tombstones(id uuid primary key default gen_random_uuid(),resource_id uuid not null,resource_type text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
do $$ declare t text;begin foreach t in array array['profiles','admin_members','service_packages','site_config','orders','order_credentials','payment_events','reading_results','attachments','reading_history','content_templates','dataset_versions','consent_events','public_media','reviews','audit_events','abuse_counters','lookup_sessions','deletion_tombstones'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);end loop;end $$;
grant select on public.service_packages to anon,authenticated;
create policy packages_read on public.service_packages for select to anon,authenticated using(active);
grant select,insert,update,delete on public.profiles,public.reading_history to authenticated;
create policy own_profile on public.profiles for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy own_history on public.reading_history for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
-- Orders/results/files intentionally have NO direct browser policies. DTOs through verified API only.
insert into storage.buckets(id,name,public,file_size_limit) values('source-photos','source-photos',false,5242880),('private-results','private-results',false,20971520),('public-derivatives','public-derivatives',false,20971520) on conflict(id) do nothing;
-- No client storage object policies. All upload paths generated by validated server workflows.
create function public.immutable_published() returns trigger language plpgsql set search_path='' as $$begin if old.state='published' then raise exception 'immutable published dataset';end if;return new;end$$;
create trigger immutable_dataset before update or delete on public.dataset_versions for each row execute function public.immutable_published();
create function public.reject_event_mutation() returns trigger language plpgsql set search_path='' as $$begin raise exception 'append only';end$$;
create trigger consent_append_only before update or delete on public.consent_events for each row execute function public.reject_event_mutation();
create trigger audit_append_only before update or delete on public.audit_events for each row execute function public.reject_event_mutation();
create function public.require_admin(p_actor uuid,p_owner boolean default false) returns void language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.admin_members where user_id=p_actor and active and (not p_owner or role='owner')) then raise exception 'forbidden';end if;end$$;
create function public.consume_limit(p_key text,p_code text,p_route text) returns jsonb language plpgsql security definer set search_path='' as $$declare n integer;m integer;g integer;w bigint:=floor(extract(epoch from now())/900);begin
 insert into public.abuse_counters(key,route,window_id,expires_at) values(p_key,p_route,w,now()+interval '30 minutes') on conflict(key,route,window_id) do update set count=public.abuse_counters.count+1 returning count into n;
 insert into public.abuse_counters(key,route,window_id,expires_at) values(p_code,p_route||':pair',w,now()+interval '30 minutes') on conflict(key,route,window_id) do update set count=public.abuse_counters.count+1 returning count into m;
 insert into public.abuse_counters(key,route,window_id,expires_at) values('global','all',w,now()+interval '30 minutes') on conflict(key,route,window_id) do update set count=public.abuse_counters.count+1 returning count into g;
 return jsonb_build_object('allowed',n<=30 and m<=5 and g<=1000,'challenge',n>=3 or m>=3);end$$;
create function public.create_order(p_key uuid,p_user uuid,p_code text,p_secret text,p_phone text,p_phone_hash text,p_package text,p_name text,p_email text,p_inputs jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.orders;p public.service_packages;c public.site_config;begin
 perform pg_advisory_xact_lock(hashtextextended(p_key::text,0));select * into o from public.orders where idempotency_key=p_key;if found then return jsonb_build_object('created',false);end if;
 select * into c from public.site_config limit 1;if c.bank is null or c.refund_policy is null or c.support is null or not c.retention_approved or not c.release_verified then raise exception 'checkout_locked';end if;
 select * into strict p from public.service_packages where code=p_package and active;
 insert into public.orders(idempotency_key,user_id,order_code,package_code,price_vnd,delivery_hours,package_version,name,phone_e164,phone_lookup_hmac,email,inputs) values(p_key,p_user,p_code,p.code,p.price_vnd,p.delivery_hours,p.version,p_name,p_phone,p_phone_hash,p_email,p_inputs) returning * into o;
 insert into public.order_credentials(order_id,secret_digest) values(o.id,p_secret);
 insert into public.consent_events(order_id,scope,granted,notice_version,age_band,actor) values(o.id,'service_processing',true,'v1',p_inputs->>'age_band',p_user);
 return jsonb_build_object('created',true,'order_code',o.order_code,'price_vnd',o.price_vnd,'expires_at',o.expires_at,'bank',c.bank);end$$;
create function public.lookup_order(p_code text,p_phone_hash text,p_digest text,p_session text,p_csrf text) returns jsonb language plpgsql security definer set search_path='' as $$declare o public.orders;r public.reading_results;d text;diff integer:=0;i integer;begin
 select * into o from public.orders where order_code=p_code;select secret_digest into d from public.order_credentials where order_id=o.id and revoked_at is null;d:=coalesce(d,repeat('0',64));
 if length(p_digest)<>64 then return null;end if;
 for i in 1..64 loop diff:=diff | (ascii(substr(d,i,1)) # ascii(substr(p_digest,i,1)));end loop;
 if diff<>0 or o.id is null or o.phone_lookup_hmac<>p_phone_hash then return null;end if;
 insert into public.lookup_sessions(token_digest,csrf_digest,order_id) values(p_session,p_csrf,o.id);
 select * into r from public.reading_results where order_id=o.id and state='published';
 return jsonb_build_object('order_code',o.order_code,'result',case when r.id is null then null else jsonb_build_object('body',r.body,'revision',r.revision) end,'attachments',case when r.id is null then '[]'::jsonb else (select coalesce(jsonb_agg(jsonb_build_object('id',id,'mime',mime,'size',size)),'[]'::jsonb) from public.attachments where order_id=o.id and classification='private_result' and release_state='released') end);end$$;
create function public.resolve_lookup(p_token text,p_csrf text) returns uuid language sql security definer set search_path='' as $$select order_id from public.lookup_sessions where token_digest=p_token and csrf_digest=p_csrf and expires_at>now() and revoked_at is null$$;
create function public.claim_transfer(p_order uuid) returns void language plpgsql security definer set search_path='' as $$declare o public.orders;begin select * into strict o from public.orders where id=p_order for update;if o.internal_state='payment_claimed' then return;end if;if o.internal_state<>'awaiting_payment' or o.expires_at<=now() then raise exception 'state';end if;update public.orders set internal_state='payment_claimed',version=version+1,updated_at=now() where id=p_order;insert into public.payment_events(order_id,kind) values(p_order,'claimed');end$$;
create function public.confirm_payment(p_actor uuid,p_order uuid,p_version integer,p_amount integer,p_reference text,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare o public.orders;begin perform public.require_admin(p_actor);select * into strict o from public.orders where id=p_order for update;
 if exists(select 1 from public.payment_events where order_id=p_order and reference=p_reference and kind in ('verified','reconciled')) then return;end if;
 if o.version<>p_version or p_amount<>o.price_vnd or not(o.internal_state in ('awaiting_payment','payment_claimed') or (o.internal_state='expired' and length(trim(p_reason))>=10)) then raise exception 'conflict';end if;
 if o.expires_at<=now() and length(trim(p_reason))<10 then raise exception 'late reconciliation reason required';end if;
 insert into public.payment_events(order_id,kind,amount,reference,actor,reason) values(p_order,case when o.expires_at<=now() then 'reconciled' else 'verified' end,p_amount,p_reference,p_actor,p_reason);
 update public.orders set internal_state='paid',paid_at=now(),version=version+1,updated_at=now() where id=p_order;
 insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'payment_confirmed',p_order,array['paid_at','internal_state']);end$$;
create function public.write_result(p_actor uuid,p_order uuid,p_body text,p_publish boolean) returns void language plpgsql security definer set search_path='' as $$declare o public.orders;n integer;begin perform public.require_admin(p_actor);select * into strict o from public.orders where id=p_order for update;
 if p_body ~ '[<>]' or length(p_body)>60000 then raise exception 'text only';end if;
 if p_publish then
 if o.internal_state not in ('paid','in_progress','ready','delivered') or array_length(regexp_split_to_array(trim(p_body),'\s+'),1)<501 then raise exception 'not publishable';end if;
 if o.package_code='G50' and not exists(select 1 from public.attachments where order_id=p_order and classification='private_result' and mime='video/mp4' and release_state='released') then raise exception 'video required';end if;
 update public.reading_results set state='archived',updated_at=now() where order_id=p_order and state='published';end if;
 select coalesce(max(revision),0)+1 into n from public.reading_results where order_id=p_order;
 insert into public.reading_results(order_id,revision,body,state,published_by,published_at) values(p_order,n,p_body,case when p_publish then 'published' else 'draft' end,case when p_publish then p_actor end,case when p_publish then now() end);
 if p_publish then update public.orders set internal_state='delivered',delivered_at=coalesce(delivered_at,now()),version=version+1,updated_at=now() where id=p_order;end if;
 insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,case when p_publish then 'result_published' else 'result_draft' end,p_order,array['revision']);end$$;
create function public.reset_credential(p_actor uuid,p_order uuid,p_digest text,p_reason text) returns void language plpgsql security definer set search_path='' as $$begin perform public.require_admin(p_actor,true);perform 1 from public.orders where id=p_order for update;if length(trim(p_reason))<20 then raise exception 'verification reason required';end if;update public.order_credentials set secret_digest=p_digest,pepper_version=1,revoked_at=null,updated_at=now() where order_id=p_order;update public.lookup_sessions set revoked_at=now() where order_id=p_order;insert into public.audit_events(actor,action,resource_id,changed_fields) values(p_actor,'credential_reset_verified',p_order,array['secret_digest','sessions']);end$$;
create function public.write_review(p_order uuid,p_rating integer,p_text text,p_nickname text) returns void language plpgsql security definer set search_path='' as $$begin perform 1 from public.orders where id=p_order and internal_state='delivered' for update;if not found or p_text ~ '[<>]' or p_nickname ~ '[<>]' then raise exception 'forbidden';end if;insert into public.reviews(order_id,rating,body,nickname) values(p_order,p_rating,p_text,p_nickname) on conflict(order_id) do update set rating=p_rating,body=p_text,nickname=p_nickname,moderation_state='pending',updated_at=now();end$$;
create function public.expire_orders() returns integer language plpgsql security definer set search_path='' as $$declare n integer;begin update public.orders set internal_state='expired',updated_at=now(),version=version+1 where internal_state in ('awaiting_payment','payment_claimed') and expires_at<=now();get diagnostics n=row_count;return n;end$$;
-- Revoke every function in this migration. Only trusted Pages Functions may call RPCs.
do $$declare f record;begin for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('require_admin','consume_limit','create_order','lookup_order','resolve_lookup','claim_transfer','confirm_payment','write_result','reset_credential','write_review','expire_orders','immutable_published','reject_event_mutation') loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end$$;

